import { mapState } from "vuex";
import uploadPictures from "@/components/uploadPictures";
import { liveAdd, liveAuchorList } from "@/api/live";
export default {
  name: "creat_live",
  components: {
    uploadPictures,
  },
  computed: {
    ...mapState("admin/layout", ["isMobile", "menuCollapse"]),
    labelWidth() {
      return this.isMobile ? undefined : 100;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  data() {
    return {
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      grid: {
        xl: 10,
        lg: 16,
        md: 18,
        sm: 24,
        xs: 24,
      },
      formValidate: {
        name: "",
        anchor_name: "",
        anchor_wechat: "",
        phone: "",
        screen_type: 0,
        close_like: 1,
        close_goods: 1,
        close_comment: 1,
        cover_img: "",
        share_img: "",
        sort: 0,
        type: 0,
        start_time: "",
      },
      screen_type: [
        {
          value: "竖屏",
          label: 0,
        },
        {
          value: "横屏",
          label: 1,
        },
      ],
      type: [
        // {
        //     value:'推流',
        //     label:1
        // },
        {
          value: "手机直播",
          label: 0,
        },
      ],
      close_like: [
        {
          value: "开启",
          label: 1,
        },
        {
          value: "关闭",
          label: 0,
        },
      ],
      close_goods: [
        {
          value: "开启",
          label: 1,
        },
        {
          value: "关闭",
          label: 0,
        },
      ],
      close_comment: [
        {
          value: "开启",
          label: 1,
        },
        {
          value: "关闭",
          label: 0,
        },
      ],
      timeVal: "",
      modalPic: false,
      isChoice: "单选",
      activeIndex: 0,
      liveList: [],
      modal3: false,
    };
  },
  mounted() {
    this.getLive();
  },
  methods: {
    cancel() {
      this.modal3 = false;
    },
    codeImg() {
      this.modal3 = true;
    },
    anchorName(e) {
      this.liveList.filter((el, index) => {
        if (el.wechat === e) {
          this.formValidate.anchor_name = el.name;
        }
      });
    },
    //主播列表；
    getLive() {
      let formValidate = {
        kerword: "",
        page: "",
        limit: "",
      };
      liveAuchorList(formValidate)
        .then((res) => {
          this.liveList = res.data.list;
        })
        .catch((error) => {
          this.$Message.error(error.msg);
        });
    },
    // 点击图文封面
    modalPicTap(type) {
      this.activeIndex = type;
      this.modalPic = true;
    },
    // 选择日期
    selectDate(e) {
      this.formValidate.start_time = e;
    },
    // 获取图片信息
    getPic(pc) {
      this.$nextTick(() => {
        if (this.activeIndex == 0) {
          this.formValidate.cover_img = pc.att_dir;
        } else {
          this.formValidate.share_img = pc.att_dir;
        }
        this.modalPic = false;
      });
    },
    // 保存
    handleSubmit(name) {
      liveAdd(this.formValidate)
        .then((res) => {})
        .then((res) => {
          this.$Message.success("添加成功");
          setTimeout(() => {
            this.$router.push({ path: "/admin/content/live/live_room" });
          }, 500);
        })
        .catch((error) => {
          this.$Message.error(error.msg);
        });
    },
  },
};
